// Invariant probe for ledgerd. Run: node invariant-probe.mjs
// Audits the three README invariants against the public API. Not part of the test suite.
import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

let failures = 0
function check(name, cond, detail = '') {
  if (cond) console.log(`  ok    ${name}`)
  else { failures++; console.log(`  FAIL  ${name}${detail ? ' — ' + detail : ''}`) }
}

function fund(accounts) {
  resetSnapshotCache()
  const ledger = createLedger()
  let sum = 0
  for (const [acc, amt] of Object.entries(accounts)) {
    ledger.append({ type: 'credit', account: acc, amountCents: amt, ts: 0, id: `fund-${acc}` })
    sum += amt
  }
  return { ledger, sum }
}

// Audit all three invariants on `ledger`; expectedSum is the conserved total.
function audit(label, ledger, expectedSum) {
  const folded = ledger.fold()
  const accounts = new Set([...Object.keys(folded), ...ledger.events().map(e => e.account)])
  let mismatch = null, negative = null, sum = 0
  for (const a of accounts) {
    const viaFold = folded[a] ?? 0
    const viaCache = getBalance(ledger, a)
    if (viaCache !== viaFold && mismatch === null) mismatch = `${a}: getBalance=${viaCache} fold=${viaFold}`
    if (viaFold < 0 && negative === null) negative = `${a}=${viaFold}`
    sum += viaFold
  }
  check(`${label} · inv3 getBalance == fold`, mismatch === null, mismatch)
  check(`${label} · inv2 no overdraft`, negative === null, negative)
  check(`${label} · inv1 conserved`, sum === expectedSum, `sum=${sum} expected=${expectedSum}`)
}

console.log('— probe 1: repeated transfers through the snapshot cache —')
{
  const { ledger, sum } = fund({ a: 10000, b: 0 })
  getBalance(ledger, 'a')                       // populate the cache
  transfer(ledger, 'a', 'b', 6000, {})
  audit('after 1st transfer', ledger, sum)
  let threw = false
  try { transfer(ledger, 'a', 'b', 5000, {}) } catch { threw = true }
  check('2nd transfer of 5000 rejected (real balance is 4000)', threw,
    threw ? 'unexpectedly threw' : 'NOT rejected — sender overdrafted')
  audit('after 2nd transfer', ledger, sum)
}

console.log('— probe 2: two ledgers interleaved without resetSnapshotCache —')
{
  resetSnapshotCache()
  const l1 = createLedger()
  l1.append({ type: 'credit', account: 'x', amountCents: 100, ts: 0, id: 'i1' })
  getBalance(l1, 'x')                           // populate the global cache from l1
  const l2 = createLedger()
  l2.append({ type: 'credit', account: 'y', amountCents: 777, ts: 0, id: 'i2' })
  check(`getBalance(l2,'y') == 777 (got ${getBalance(l2, 'y')})`, getBalance(l2, 'y') === 777)
  check(`getBalance(l2,'x') == 0 (got ${getBalance(l2, 'x')})`, getBalance(l2, 'x') === 0)
}

console.log('— probe 3: NaN amount poisons the ledger —')
{
  const { ledger, sum } = fund({ a: 5000, b: 0 })
  let threw = false
  try { transfer(ledger, 'a', 'b', NaN, {}) } catch { threw = true }
  check('NaN transfer rejected', threw, 'accepted — fold now returns NaN, conservation broken')
  audit('after NaN attempt', ledger, sum)
  let threw2 = false
  try { transfer(ledger, 'a', 'b', 10.5, {}) } catch { threw2 = true }
  check('fractional-cents transfer rejected', threw2, 'accepted')
}

console.log('— probe 4: caller-supplied seq must not corrupt stream ordering —')
{
  const ledger = createLedger()
  ledger.append({ seq: 999, type: 'credit', account: 'a', amountCents: 1, ts: 0, id: 'z' })
  check(`events()[0].seq === 0 (got ${JSON.stringify(ledger.events()[0].seq)})`, ledger.events()[0].seq === 0)
}

console.log('— probe 5: rebate rate >= 100 must not chase itself forever —')
{
  const { ledger } = fund({ a: 10000, b: 0 })
  let outcome = 'returned normally'
  try { transfer(ledger, 'a', 'b', 1000, { onSettled: createRebateHook(ledger, 100) }) }
  catch (e) { outcome = `threw ${e.constructor.name}: ${String(e.message).slice(0, 60)}` }
  check('100% rebate terminates cleanly', outcome === 'returned normally' || /^threw Error/.test(outcome),
    `bad outcome: ${outcome}`)
}

console.log('— probe 6: randomized fuzz (300 ops, rebate chains, cache resets) —')
{
  const names = ['p', 'q', 'r', 's']
  const { ledger, sum } = fund(Object.fromEntries(names.map(n => [n, 50000])))
  const rebate = createRebateHook(ledger, 10)
  let seed = 42
  const rand = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648
  for (let i = 0; i < 300; i++) {
    if (i % 97 === 0) resetSnapshotCache()
    const from = names[Math.floor(rand() * names.length)]
    let to = names[Math.floor(rand() * names.length)]
    if (to === from) to = names[(names.indexOf(from) + 1) % names.length]
    const amount = 1 + Math.floor(rand() * 4000)
    try {
      transfer(ledger, from, to, amount, i % 2 === 0 ? { onSettled: rebate } : {})
    } catch (e) {
      if (!/insufficient funds/.test(e.message)) throw e
    }
    audit(`fuzz op ${i + 1}`, ledger, sum)
  }
}

console.log(failures === 0 ? '\nALL PROBES PASS' : `\n${failures} PROBE FAILURE(S)`)
process.exitCode = failures === 0 ? 0 : 1

/**
 * Balance snapshot cache. Folding the full stream on every read is expensive,
 * so each ledger keeps a snapshot: a full fold taken at `atCount` events. A
 * read first brings the snapshot exactly level with the current stream, either
 * by re-folding in full (due at most once every REFRESH_EVERY events) or by
 * applying just the events appended after the snapshot on top of it. The
 * returned balance therefore always equals a fold of the current event stream
 * (invariant 3), which also means transfers validated through this read path
 * can never overdraft (invariant 2).
 */
const REFRESH_EVERY = 8

// One cache entry per ledger object, so interleaved reads on different
// ledgers can never serve one ledger's balances for another's.
let caches = new WeakMap()

function applyEvent(balances, event) {
  const delta = event.type === 'credit' ? event.amountCents : -event.amountCents
  balances.set(event.account, (balances.get(event.account) ?? 0) + delta)
}

export function getBalance(ledger, account) {
  const count = ledger.eventCount()
  let entry = caches.get(ledger)

  if (entry === undefined || count < entry.atCount || count - entry.atCount >= REFRESH_EVERY) {
    // Full refresh: no snapshot for this ledger yet, or enough events have
    // accumulated since it was taken. The base is taken from fold() itself so
    // it matches the canonical reconstruction by construction. (count <
    // atCount cannot happen on an append-only stream; treat it as stale.)
    entry = { atCount: count, balances: new Map(Object.entries(ledger.fold())) }
    caches.set(ledger, entry)
  } else if (count > entry.atCount) {
    // Snapshot is close enough to the stream: apply just the events appended
    // after it, in stream order — the same reduction fold() performs.
    const events = ledger.events()
    for (let i = entry.atCount; i < count; i++) applyEvent(entry.balances, events[i])
    entry.atCount = count
  }

  return entry.balances.get(account) ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

