// Verifies the snapshot cache still bounds full folds to at most one per REFRESH_EVERY events.
import { createLedger, transfer, getBalance, resetSnapshotCache } from './src/index.js'

resetSnapshotCache()
const ledger = createLedger()
ledger.append({ type: 'credit', account: 'a', amountCents: 100000, ts: 0, id: 'fund' })
const origFold = ledger.fold.bind(ledger)
let folds = 0
ledger.fold = (...args) => { folds++; return origFold(...args) }

for (let i = 0; i < 50; i++) transfer(ledger, 'a', 'b', 10, {})
const viaCache = getBalance(ledger, 'a')
const viaFold = origFold().a
console.log(`transfers=50 (100 events), full folds invoked=${folds}, getBalance=${viaCache}, fold=${viaFold}, exact=${viaCache === viaFold}`)
console.log(folds <= Math.ceil(100 / 8) && viaCache === viaFold ? 'CACHE BOUNDS OK' : 'CACHE BOUNDS BROKEN')
